//! The settings surface, as the document a settings panel reads.
//!
//! The panel needs to know, for every setting an engine is expected to
//! understand, whether this one honours it: a control that changes nothing is
//! worse than an absent one, so the surface says `applied`, `partial`, `missing`
//! or `n/a` for each row and the panel hides or disables the rest.
//!
//! The document is generated by `tools/gen-settings-ledger.py` in the same run
//! that writes `docs/SETTINGS-LEDGER.md`, from the same measurement, so a panel
//! and the ledger cannot disagree about a setting. It is not hand-written and
//! must not be edited by hand: `fish scripts/test-hfw.fish` fails when it is
//! stale.

/// The settings surface as JSON.
///
/// The document carries `surface`, `version`, `counts`, `statuses`,
/// `capabilities`, `locations` and `settings`. Each setting carries `name` (the
/// dialect name), `hfw` (the key this engine uses when it differs), `tier`,
/// `status`, `type`, `default`, `unit`, `location`, `category`, `source` and
/// `per_object`: whether a panel may set it on one object as well as on the
/// job. Each capability is a feature this engine will not build, carrying `id`,
/// `title`, `disposition`, `panel`, `note` and `instead`, so a panel can show the
/// control as unavailable and say what to use.
pub fn json() -> &'static str {
    include_str!("../assets/settings-surface.json")
}

/// Version of the document's shape, which a reader compares against.
///
/// It changes when a field is removed or renamed, so a panel built against an
/// older document refuses rather than guessing at what a field means.
pub const VERSION: u32 = 2;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_document_starts_and_ends_like_json() {
        let text = json();
        assert!(
            text.starts_with('{'),
            "the document does not open an object"
        );
        assert!(
            text.trim_end().ends_with('}'),
            "the document does not close one"
        );
        assert!(text.contains("\"surface\": \"hfw-settings\""));
        assert!(text.contains(&format!("\"version\": {VERSION}")));
    }

    #[test]
    fn every_setting_carries_one_of_the_four_statuses() {
        let text = json();
        let rows = text.matches("\"name\":").count();
        assert!(rows > 300, "only {rows} settings in the surface");
        let counted = ["applied", "partial", "missing", "n/a"]
            .iter()
            .map(|status| text.matches(&format!("\"status\": \"{status}\"")).count())
            .sum::<usize>();
        assert_eq!(counted, rows, "{rows} settings, {counted} statuses");
    }

    #[test]
    fn a_setting_is_only_offered_per_object_when_the_engine_honours_it() {
        let text = json();
        let offered = text.matches("\"per_object\": true").count();
        assert!(
            offered > 40,
            "only {offered} settings are offered per object"
        );
        assert!(
            offered < text.matches("\"name\":").count(),
            "every setting is offered per object, which cannot be right"
        );
        let mut rows = text.split("\"name\":");
        rows.next();
        for row in rows {
            let row = row.split("},").next().unwrap_or_default();
            if row.contains("\"per_object\": true") {
                assert!(
                    row.contains("\"status\": \"applied\""),
                    "a row is offered per object without being applied: {row}"
                );
            }
        }
    }

    #[test]
    fn every_capability_is_a_feature_this_engine_declines_and_says_what_to_use() {
        let text = json();
        assert!(
            text.contains("\"capabilities\":"),
            "the surface has no capabilities"
        );
        let listed = text.matches("\"disposition\": \"out_of_scope\"").count();
        assert_eq!(listed, 7, "{listed} out-of-scope capabilities");
        assert_eq!(text.matches("\"panel\": \"unavailable\"").count(), listed);
        assert_eq!(text.matches("\"title\":").count(), listed);
        assert_eq!(text.matches("\"instead\":").count(), listed);
        let mut ids = Vec::new();
        for row in text.split("\"id\":") {
            let id = row.trim_start().split('"').nth(1).unwrap_or_default();
            if !id.is_empty() && !id.contains(':') && row.contains("out_of_scope") {
                ids.push(id.to_owned());
            }
        }
        ids.sort();
        let before = ids.len();
        ids.dedup();
        assert_eq!(ids.len(), before, "two capabilities share an id");
    }

    #[test]
    fn every_setting_names_a_location_and_a_type() {
        let text = json();
        let rows = text.matches("\"name\":").count();
        assert_eq!(text.matches("\"location\":").count(), rows);
        assert_eq!(text.matches("\"type\":").count(), rows);
        assert_eq!(text.matches("\"category\":").count(), rows);
    }
}
